namespace Mono.Linker.Tests.Cases.Inheritance.Interfaces.RecursiveInterfaces
{
    /// <summary>
    /// Each interface lists every interface it inherits, so an interface at the end of a deep chain is reachable
    /// through exponentially many paths. Mapping its interfaces and default implementations must visit each interface
    /// once, or this test does not finish (COM interop generated by [GeneratedComInterface] has chains this deep).
    /// </summary>
    class DeepInterfaceHierarchy
    {
        public static void Main()
        {
        }

        interface I1 { void M1(); }
        interface I2 : I1 { void M2(); }
        interface I3 : I2 { void M3(); }
        interface I4 : I3 { void M4(); }
        interface I5 : I4 { void M5(); }
        interface I6 : I5 { void M6(); }
        interface I7 : I6 { void M7(); }
        interface I8 : I7 { void M8(); }
        interface I9 : I8 { void M9(); }
        interface I10 : I9 { void M10(); }
        interface I11 : I10 { void M11(); }
        interface I12 : I11 { void M12(); }
        interface I13 : I12 { void M13(); }
        interface I14 : I13 { void M14(); }
        interface I15 : I14 { void M15(); }
        interface I16 : I15 { void M16(); }
        interface I17 : I16 { void M17(); }
        interface I18 : I17 { void M18(); }
        interface I19 : I18 { void M19(); }
        interface I20 : I19 { void M20(); }
        interface I21 : I20 { void M21(); }
        interface I22 : I21 { void M22(); }
        interface I23 : I22 { void M23(); }
        interface I24 : I23 { void M24(); }
        interface I25 : I24 { void M25(); }
        interface I26 : I25 { void M26(); }
        interface I27 : I26 { void M27(); }
        interface I28 : I27 { void M28(); }

        interface ILeaf : I28 { }
    }
}
